        'resolved_help_html' => 'இந்த நிலையில் உள்ள சம்பவங்கள் <code>resolved_datetime</code> ஐ தானாகப் பதிவு செய்து, செயலில் உள்ள டாஷ்போர்டிலிருந்து விலகுகின்றன.',
        'field_severity' => 'தீவிர வரிசை',
        'severity_help' => '1 = மோசமானது (பெரிய செயலிழப்பு). அதிகம் = குறைந்த தீவிரம்.',
        'field_downtime' => 'இந்த நிலையில் உள்ள நேரம் செயலிழப்பு நேரமாகக் கணக்கிடப்படும்',
        'downtime_help' => 'திட்டமிட்ட பராமரிப்புக்கு இதை அணைக்கவும். பராமரிப்பைக் கணக்கிட்டால் நன்கு நடத்தப்படும் சேவை புறக்கணிக்கப்பட்டதை விட மோசமாகத் தெரியும், எனவே இயல்பாக விலக்கப்பட்டுள்ளது.',
