    'help' => [
        'page_title' => 'சேவை நிலை வழிகாட்டி',
        'guide' => 'வழிகாட்டி',
        'nav_overview' => 'மேலோட்டம்',
        'nav_dashboard' => 'நிலை டாஷ்போர்டு',
        'nav_services' => 'சேவைகளை நிர்வகித்தல்',
        'nav_history' => 'சம்பவ வரலாறு',
        'nav_uptime' => 'அப்டைம் & வரலாறு',
        'nav_settings' => 'அமைப்புகள்',
        'uptime_heading' => 'அப்டைமும் சேவை வரலாறும்',
        'uptime_p1_html' => 'ஒவ்வொரு சேவையின் அட்டையிலும் <strong>வரலாறும் அப்டைமும்</strong> இணைப்பு உள்ளது. இது கடந்த 7, 30, 90 அல்லது 365 நாட்களுக்கான நாள்வாரிப் பட்டையையும், அந்தக் காலத்தில் சேவை கிடைத்த சதவீதத்தையும், ஒரு குறிப்பிட்ட பாதிப்பு நிலையில் அது இருந்த ஒவ்வொரு காலத்தையும் காட்டுகிறது.',
        'uptime_p2_html' => 'இவற்றில் எதுவும் நீங்கள் பராமரிக்க வேண்டிய தனிப் பதிவு அல்ல: அவை உங்கள் சம்பவங்களிலிருந்து கணக்கிடப்படுகின்றன. அதாவது இந்த வசதி வருவதற்கு முன் நடந்த செயலிழப்புகளையும் இது ஏற்கனவே உள்ளடக்குகிறது &mdash; ஆனால் <strong>சம்பவங்கள் பதிவு செய்யப்படும் விதத்தைப் பொறுத்தே எண்கள் துல்லியமாக இருக்கும்</strong> என்பதும் இதன் பொருள், இந்தப் பகுதியின் மீதி அதைப் பற்றியது.',
        'uptime_record_heading' => 'வரலாறு சரியாக இருக்க செயலிழப்பைப் பதிவு செய்தல்',
        'uptime_record_p_html' => 'ஒரு சம்பவம் சேவையை செயலிழப்பு நேரமாகக் கணக்கிடப்படும் நிலையில் வைக்கும் கணத்திலிருந்து, வேறு ஏதாவது சொல்லும் கணம் வரை அது செயலிழந்ததாகக் கணக்கிடப்படுகிறது. ஒவ்வொரு முறை சம்பவத்தைச் சேமிக்கும்போதும், எந்தச் சேவைகள் எந்த நிலையில் இருந்தன என்பதன் ஒரு ஸ்னாப்ஷாட்டை FreeITSM பதிவு செய்கிறது &mdash; எனவே துல்லியமான வரலாற்றைப் பெற, நிலைமை மாறும்போது <strong>சம்பவத்தைப் புதுப்பிப்பதே</strong> வழி.',
        'uptime_step1_html' => 'பாதிக்கப்பட்ட ஒவ்வொரு சேவையுடனும் அதன் பாதிப்பு நிலையுடனும் <strong>சம்பவத்தை உருவாக்குங்கள்</strong>. அதுவே தொடக்க நேரம்.',
        'uptime_step2_html' => '<strong>ஏதாவது மாறும் ஒவ்வொரு முறையும் மீண்டும் சேமியுங்கள்</strong> &mdash; ஒரு சேவை மோசமடைந்தாலும், மேம்பட்டாலும், அல்லது திரும்பி வந்தாலும். அந்தச் சேவையின் பாதிப்பு நிலையை மாற்றுங்கள், அல்லது முழுமையாக மீட்கப்பட்டிருந்தால் சம்பவத்திலிருந்து அதை அகற்றுங்கள். ஒவ்வொரு சேமிப்பிலும் நேரமுத்திரை இடப்படும், எனவே ஒரு நாள் Major Outage-இலும் எட்டு மணி நேரம் Degraded-இலும் இருந்த சேவை சரியாக அப்படியே பதிவாகும்.',
        'uptime_step3_html' => 'எல்லாம் திரும்பியதும் <strong>சம்பவத்தைத் தீர்த்து</strong> விடுங்கள். இன்னும் பட்டியலில் உள்ளவற்றுக்கு அதுவே முடிவு நேரம்.',
        'uptime_resolve_note_html' => 'சேவைகளை ஒவ்வொன்றாக அகற்ற வேண்டியதில்லை &mdash; ஆனால் அகற்றினால், முழுச் சம்பவமும் தீர்க்கப்படும் நேரத்தில் அல்லாமல், ஒவ்வொன்றும் அந்தக் கணத்திலேயே கணக்கிடப்படுவது நிற்கும். &ldquo;கோப்பு சர்வர் இரண்டு நாட்கள் செயலிழந்தது&rdquo; என்பதற்கும் &ldquo;எல்லாம் மூன்று நாட்கள் செயலிழந்தது&rdquo; என்பதற்கும் உள்ள வேறுபாடு அதுவே.',
        'uptime_counts_heading' => 'எது செயலிழப்பு நேரமாகக் கணக்கிடப்படும்',
        'uptime_counts_p_html' => 'ஒவ்வொரு பாதிப்பு நிலையும் தனக்காகத் தானே முடிவு செய்கிறது, <strong>அமைப்புகள் &rarr; பாதிப்பு நிலைகள்</strong> என்பதில். Major Outage, Partial Outage மற்றும் Degraded இயல்பாகக் கணக்கிடப்படும்; Maintenance, Operational மற்றும் No Disruption கணக்கிடப்படாது. திட்டமிட்ட பராமரிப்பு வேண்டுமென்றே விலக்கப்பட்டுள்ளது &mdash; அதைக் கணக்கிட்டால் நன்கு நடத்தப்படும் சேவை புறக்கணிக்கப்பட்டதை விட மோசமாகத் தெரியும். நீங்களே சேர்க்கும் எந்த நிலையும் நீங்கள் வேறுவிதமாகச் சொல்லும் வரை கணக்கிடப்படும்.',
        'uptime_reading_heading' => 'பட்டையைப் படித்தல்',
        'uptime_read_green_html' => '<strong>பச்சை</strong> &mdash; அந்த நாளில் எந்தச் சம்பவமும் சேவையைப் பாதிக்கவில்லை.',
        'uptime_read_red_html' => '<strong>சிவப்பு</strong> &mdash; ஒரு சம்பவம் அப்டைமுக்கு எதிராகக் கணக்கிடப்பட்டது. நிறம் என்பது பாதிப்பு நிலை; எது என்பதைப் பார்க்க மேலே சுட்டியை வையுங்கள்.',
        'uptime_read_grey_html' => '<strong>சாம்பல்</strong> &mdash; ஒரு சம்பவம் சேவையைப் பாதித்தது, ஆனால் திட்டமிட்ட பராமரிப்பு போன்ற கணக்கிடப்படாத நிலையில். உண்மையில் எந்த நிலை என்பதைப் பார்க்க மேலே சுட்டியை வையுங்கள்.',
        'uptime_tip_html' => 'நீங்கள் எதிர்பார்ப்பதை விட மிக மோசமான அப்டைம் காட்டும் சேவை பொதுவாக யாரும் தீர்க்காத ஒரு சம்பவத்தைக் குறிக்கும் &mdash; திறந்த சம்பவம் மூடப்படும் வரை கணக்கிடப்படும். எண் தவறு என்று கருதுவதற்கு முன் சம்பவப் பட்டியலைச் சரிபாருங்கள்.',
        'nav_tips' => 'விரைவு குறிப்புகள்',
        'hero_title' => 'சேவை நிலை வழிகாட்டி',
        'hero_sub' => 'உங்கள் IT சேவைகளைக் கண்காணியுங்கள், சம்பவங்களைத் தெரிவியுங்கள், மற்றும் பங்குதாரர்களை நிகழ்நேரத்தில் தகவலறிந்து வைத்திருங்கள்.',
        'overview_heading' => 'மேலோட்டம்',
        'overview_intro' => 'உங்கள் நிறுவனம் சார்ந்திருக்கும் ஒவ்வொரு IT சேவையின் ஆரோக்கியம் குறித்த ஒருங்கிணைந்த பார்வையை சேவை நிலை தொகுதி உங்களுக்கு வழங்குகிறது. ஏதேனும் தவறு நேர்ந்தால், சம்பவங்களைப் பதிவு செய்யலாம், பாதிக்கப்பட்ட சேவைகளைப் புதுப்பிக்கலாம், மற்றும் தீர்வு செயல்முறை முழுவதும் பயனர்களை தகவலறிந்து வைத்திருக்கலாம்.',
        'feature_dashboard_title' => 'நிலை டாஷ்போர்டு',
        'feature_dashboard_desc' => 'ஒவ்வொரு சேவையின் தற்போதைய ஆரோக்கியத்தை ஒரே பார்வையில் காணுங்கள். ஒவ்வொரு சேவையும் செயல்பாட்டில் உள்ளதா, மந்தமாக உள்ளதா, பராமரிப்பில் உள்ளதா அல்லது செயலிழப்பை சந்திக்கிறதா என்பதை நிற-குறியீட்டு பேட்ஜ்கள் காட்டுகின்றன.',
        'feature_incident_title' => 'சம்பவக் கண்காணிப்பு',
        'feature_incident_desc' => 'தலைப்புகள், நிலை புதுப்பிப்புகள் மற்றும் கருத்துகளுடன் சம்பவங்களைப் பதிவு செய்யுங்கள். எது, ஏன் பாதிக்கப்படுகிறது என்பதை அனைவரும் சரியாக அறிய ஒவ்வொரு சம்பவத்துடனும் பாதிக்கப்பட்ட சேவைகளை இணைக்கவும்.',
        'feature_management_title' => 'சேவை மேலாண்மை',
        'feature_management_desc' => 'அமைப்புகளில் உங்கள் சேவை அட்டவணையை அமைக்கவும். பெயர்கள், விளக்கங்கள் மற்றும் காட்சி வரிசையுடன் சேவைகளைச் சேர்க்கவும். உங்கள் உள்கட்டமைப்பு வளர்ச்சியடையும்போது சேவைகளை செயல்படுத்தவும் அல்லது செயலிழக்கச் செய்யவும்.',
        'feature_comms_title' => 'தொடர்பு',
        'feature_comms_desc' => 'நிகழ்நேர நிலை புதுப்பிப்புகளுடன் பங்குதாரர்களை தகவலறிந்து வைத்திருங்கள். ஒவ்வொரு சம்பவமும் ஒரு நிலையையும் கருத்து தடத்தையும் கொண்டிருப்பதால், பயனர்கள் சேவை மேசையைத் துரத்தாமலேயே தீர்வு முன்னேற்றத்தைப் பின்தொடரலாம்.',
        'dashboard_heading' => 'நிலை டாஷ்போர்டு',
        'dashboard_p1' => 'சேவை நிலை தொகுதியைத் திறக்கும்போது நீங்கள் முதலில் காண்பது டாஷ்போர்டு ஆகும். இது சேவை அட்டைகளின் ஒரு கட்டத்தைக் காண்பிக்கிறது, ஒவ்வொன்றும் சேவை பெயர், ஒரு சுருக்க விளக்கம், மற்றும் அதன் தற்போதைய மோசமான நிலையைப் பிரதிபலிக்கும் நிற-குறியீட்டு பாதிப்பு பேட்ஜைக் காட்டுகிறது. கட்டத்திற்குக் கீழே சமீபத்திய மற்றும் செயலில் உள்ள அனைத்து சம்பவங்களையும் பட்டியலிடும் சம்பவ அட்டவணை அமைந்துள்ளது.',
        'dashboard_p2_html' => 'ஒவ்வொரு சேவை அட்டையும், செயலில் (தீர்க்கப்படாத) எந்தச் சம்பவத்திலிருந்தும் அதற்கு ஒதுக்கப்பட்ட மிகவும் தீவிரமான பாதிப்பு நிலையைத் தானாகவே பிரதிபலிக்கிறது. ஒரு சேவையைப் பாதிக்கும் அனைத்து சம்பவங்களும் தீர்க்கப்படும்போது, அது <strong>செயல்பாட்டில்</strong> நிலைக்குத் திரும்புகிறது.',
        'status_levels' => 'நிலை மட்டங்கள்',
        'level_operational_name' => 'செயல்பாட்டில்',
        'level_operational_desc' => 'அறியப்பட்ட சிக்கல்கள் இல்லாமல் சேவை இயல்பாக இயங்குகிறது. இது அனைத்து ஆரோக்கியமான சேவைகளுக்கும் இயல்புநிலை.',
        'level_degraded_name' => 'மந்தமான செயல்திறன்',
        'level_degraded_desc' => 'சேவை கிடைக்கிறது ஆனால் எதிர்பார்த்ததை விட மெதுவாக அல்லது குறைந்த செயல்பாட்டுடன் இயங்குகிறது. பயனர்கள் தாமதங்களைக் கவனிக்கலாம்.',
        'level_maintenance_name' => 'பராமரிப்பில்',
        'level_maintenance_desc' => 'திட்டமிடப்பட்ட செயலிழப்பு அல்லது பராமரிப்பு கால அளவு. வேலை மேற்கொள்ளப்படும்போது சேவை தற்காலிகமாகக் கிடைக்காமல் போகலாம்.',
        'level_outage_name' => 'பெரிய செயலிழப்பு',
        'level_outage_desc' => 'சேவை முற்றிலும் கிடைக்கவில்லை. இது மிகவும் தீவிரமான நிலை மற்றும் உடனடி விசாரணையைத் தூண்ட வேண்டும்.',
        'dashboard_tip' => 'பாதிப்பு நிலைகள் படிநிலையானவை. ஒரு சேவை பல செயலில் உள்ள சம்பவங்களுடன் இணைக்கப்பட்டிருந்தால், டாஷ்போர்டு மோசமான பாதிப்பைக் காட்டுகிறது. எடுத்துக்காட்டாக, ஒரு சம்பவம் சேவையை மந்தமானது எனக் குறிப்பதும், மற்றொன்று அதை பெரிய செயலிழப்பு எனக் குறிப்பதும், பெரிய செயலிழப்பு காண்பிக்கப்படுவதில் முடியும்.',
        'services_heading_html' => 'சேவைகளை நிர்வகித்தல் &amp; சம்பவங்களைப் பதிவு செய்தல்',
        'services_intro' => 'சேவைகள் உங்கள் நிலை பக்கத்தின் கட்டுமானக் கூறுகள். ஒவ்வொன்றும் உங்கள் பயனர்கள் சார்ந்திருக்கும் ஒரு IT சேவை, அமைப்பு அல்லது உள்கட்டமைப்புக் கூறைக் குறிக்கிறது. ஏதேனும் தவறு நேர்ந்தால், நீங்கள் ஒரு சம்பவத்தை உருவாக்கி பாதிக்கப்பட்ட சேவைகளுடன் இணைக்கிறீர்கள்.',
        'add_incident_heading' => 'புதிய சம்பவத்தைச் சேர்த்தல்',
        'add_incident_step1_html' => 'சம்பவ படிவத்தைத் திறக்க டாஷ்போர்டில் <strong>"புதியது" கிளிக் செய்யவும்</strong>.',
        'add_incident_step2_html' => '<strong>ஒரு தலைப்பை உள்ளிடவும்</strong> &mdash; சிக்கலின் சுருக்கமான, தெளிவான விளக்கம். எடுத்துக்காட்டாக: "மின்னஞ்சல் வழங்கல் தாமதங்கள்" அல்லது "VPN நுழைவாயில் அணுக முடியவில்லை".',
        'add_incident_step3_html' => '<strong>நிலையை அமைக்கவும்</strong> &mdash; விசாரிக்கிறது, கண்டறியப்பட்டது, மூன்றாம் தரப்பு, கண்காணிப்பு அல்லது தீர்க்கப்பட்டது என்பதைத் தேர்ந்தெடுக்கவும். விசாரிக்கிறது என்பதிலிருந்து தொடங்கி, மேலும் அறிந்தவாறு புதுப்பிக்கவும்.',
        'add_incident_step4_html' => '<strong>ஒரு கருத்தைச் சேர்க்கவும்</strong> &mdash; இதுவரை அறியப்பட்டவை, எடுக்கப்படும் நடவடிக்கைகள், மற்றும் பயனர்களுக்குக் கிடைக்கும் தற்காலிக தீர்வுகளை விவரிக்கவும்.',
        'add_incident_step5_html' => '<strong>பாதிக்கப்பட்ட சேவைகளை இணைக்கவும்</strong> &mdash; ஒன்று அல்லது அதற்கு மேற்பட்ட சேவைகளைச் சேர்த்து, ஒவ்வொன்றுக்கும் பாதிப்பு நிலையைத் தேர்ந்தெடுக்கவும் (பெரிய செயலிழப்பு, பகுதி செயலிழப்பு, மந்தமானது, பராமரிப்பு, செயல்பாட்டில் அல்லது இடையூறு இல்லை).',
        'add_incident_step6_html' => '<strong>சேமிக்கவும்</strong> &mdash; சம்பவம் அட்டவணையில் தோன்றும் மற்றும் பாதிக்கப்பட்ட சேவை அட்டைகள் டாஷ்போர்டில் உடனடியாகப் புதுப்பிக்கப்படும்.',
        'workflow_heading' => 'சம்பவ நிலை பணிப்பாய்வு',
        'workflow_investigating' => 'விசாரிக்கிறது',
        'workflow_identified' => 'கண்டறியப்பட்டது',
        'workflow_monitoring' => 'கண்காணிப்பு',
        'workflow_resolved' => 'தீர்க்கப்பட்டது',
        'workflow_note_html' => 'மூல காரணம் வெளிப்புற விற்பனையாளர் அல்லது வழங்குநரிடம் இருக்கும்போது <strong>மூன்றாம் தரப்பு</strong> ஐப் பயன்படுத்தவும்.',
        'services_tip' => 'அட்டவணையில் உள்ள எந்தச் சம்பவத்தின் தலைப்பையும் கிளிக் செய்வதன் மூலம் அதைத் திருத்தலாம். நிலைமை மாறும்போது நிலையைப் புதுப்பிக்கவும், புதிய கருத்துகளைச் சேர்க்கவும் அல்லது பாதிக்கப்பட்ட சேவைகளை மாற்றவும். சம்பவங்களைப் புதுப்பித்து வைத்திருப்பது வெளிப்படையான தொடர்புக்கு முக்கியமானது.',
        'history_heading' => 'சம்பவ வரலாறு',
        'history_p1' => 'டாஷ்போர்டில் உள்ள சம்பவ அட்டவணை செயலில் உள்ள மற்றும் தீர்க்கப்பட்ட சம்பவங்கள் இரண்டையும் காட்டுகிறது, இது உங்களுக்கு சேவை ஆரோக்கியத்தின் முழுமையான காலவரிசையை வழங்குகிறது. ஒவ்வொரு வரிசையும் சம்பவத் தலைப்பு, தற்போதைய நிலை, அவற்றின் பாதிப்பு நிலைகளுடன் பாதிக்கப்பட்ட சேவைகள், மற்றும் கடைசியாகப் புதுப்பிக்கப்பட்ட நேரமுத்திரையைக் காண்பிக்கிறது.',
        'history_field_title_html' => '<strong>தலைப்பு</strong> &mdash; திருத்துவதற்காக சம்பவத்தைத் திறக்கும் கிளிக் செய்யக்கூடிய இணைப்பு. வரலாறு எளிதாக மேற்பார்வையிட தெளிவான, விளக்கமான தலைப்புகளைப் பயன்படுத்தவும்.',
        'history_field_status_html' => '<strong>நிலை</strong> &mdash; தற்போதைய விசாரணை கட்டத்தைக் காட்டும் நிற-குறியீட்டு பேட்ஜ் (விசாரிக்கிறது, கண்டறியப்பட்டது, மூன்றாம் தரப்பு, கண்காணிப்பு அல்லது தீர்க்கப்பட்டது).',
        'history_field_affected_html' => '<strong>பாதிக்கப்பட்ட சேவைகள்</strong> &mdash; ஒவ்வொரு இணைக்கப்பட்ட சேவையையும் அதன் பாதிப்பு நிலை நிறத்துடன் காட்டும் குறிச்சொல் பேட்ஜ்கள். ஒரே பார்வையில் எது, எவ்வளவு கடுமையாகப் பாதிக்கப்படுகிறது என்பதைக் காணலாம்.',
        'history_field_updated_html' => '<strong>புதுப்பிக்கப்பட்டது</strong> &mdash; மிக சமீபத்திய மாற்றத்தின் நேரமுத்திரை. தீர்க்கப்பட்ட சம்பவங்கள் மங்கலான உரையுடன் வடிவமைக்கப்படுவதால் செயலில் உள்ள சம்பவங்கள் காட்சிரீதியாகத் தனித்துத் தெரிகின்றன.',
        'history_field_actions_html' => '<strong>செயல்கள்</strong> &mdash; சம்பவத்தைத் திறக்காமலே திருத்தவும், தீர்க்கவும் அல்லது நீக்கவும்.',
        'actions_heading' => 'சம்பவத்தின் மீது நடவடிக்கை எடுத்தல்',
        'actions_p1' => 'ஒவ்வொரு சம்பவமும் <strong>செயல்கள்</strong> நெடுவரிசையில் மூன்று பொத்தான்களைக் கொண்டுள்ளது, அதே செயல்கள் <strong>வலது-கிளிக்</strong> மெனுவிலும் உள்ளன, அங்கு அவை படங்களாக அல்லாமல் பெயர்களாக உள்ளன. சம்பவத் தலைப்பு இன்னும் முழுத் திருத்தியின் இணைப்பாகவே உள்ளது, இப்போது இணைப்பாகவே தெரிகிறது.',
        'actions_edit' => '<strong>திருத்து</strong> &mdash; மாற்றங்களுக்காகச் சம்பவத்தைத் திறக்கிறது: அதன் தலைப்பு, நிலை, கருத்து மற்றும் அது பாதிக்கும் சேவைகள்.',
        'actions_resolve' => '<strong>தீர்</strong> &mdash; ஒரே கிளிக்கில் சம்பவத்தை <em>தீர்க்கப்பட்டது</em> எனக் குறிக்கப்பட்ட உங்கள் முதல் நிலைக்கு அமைக்கிறது. பாதிக்கப்பட்ட சேவைகள் இயல்பு நிலைக்குத் திரும்பும், தீர்வு நேரம் முத்திரையிடப்படும், வரலாறு சரியாகப் படிக்கும்படி சம்பவத்தின் புதுப்பிப்புகளில் ஒரு வரி சேர்க்கப்படும். சம்பவத்தைப் பற்றி வேறு எதுவும் மாற்றப்படாது. ஏற்கனவே தீர்க்கப்பட்ட சம்பவத்தில் இது வழங்கப்படாது.',
        'actions_delete' => '<strong>நீக்கு</strong> &mdash; சம்பவத்தையும் அதன் புதுப்பிப்புகளையும் அகற்றுகிறது. செயல்தவிர்ப்பு இல்லை, எனவே முதலில் கேட்கும்.',
        'actions_updates' => 'வலது-கிளிக் மெனு <strong>புதுப்பிப்புகளைக் காட்டு</strong> என்பதையும் வழங்குகிறது, தலைப்பின் அருகிலுள்ள இணைப்பு திறக்கும் அதே உரையாடல்.',
        'actions_tip' => 'எந்த நிலையும் தீர்க்கப்பட்டதாகக் குறிக்கப்படவில்லை என்று <strong>தீர்</strong> தெரிவித்தால், அமைப்புகள் &rarr; சம்பவ நிலைகள் என்பதன் கீழ் ஒன்றைச் சேர்த்து <em>தீர்க்கப்பட்டது</em> என்பதைத் தேர்வுசெய்யுங்கள். அவ்வாறு எதுவும் குறிக்கப்படும் வரை, உங்கள் நிலைகளில் எது சம்பவம் முடிந்தது என்று பொருள்படும் என்பதை FreeITSM அறிய வழியில்லை.',
        'history_p2' => 'தீர்க்கப்பட்ட சம்பவங்கள் வரலாற்றுப் பதிவாக அட்டவணையில் காணக்கூடியதாக இருக்கும். இது மீண்டும் மீண்டும் ஏற்படும் சிக்கல்களைக் கண்டறியவும், கடந்த சம்பவங்கள் எவ்வாறு கையாளப்பட்டன என்பதை மதிப்பாய்வு செய்யவும், அடிப்படை சிக்கல்களைச் சுட்டிக்காட்டக்கூடிய வடிவங்களைக் கண்டறியவும் எளிதாக்குகிறது.',
        'history_tip' => 'உங்கள் சம்பவ வரலாற்றை தவறாமல் மதிப்பாய்வு செய்வது அடிக்கடி இடையூறு செய்யப்படும் சேவைகளைக் கண்டறிய உதவுகிறது. அதே சேவை பல சம்பவங்களில் தோன்றினால், மூல காரணத்தை ஆழமாக விசாரிக்க அல்லது உள்கட்டமைப்பு மேம்படுத்தலைத் திட்டமிட வேண்டிய நேரமாக இருக்கலாம்.',
        'vis_heading' => 'உள்ளக குறிப்புகளும் வெளி புதுப்பிப்புகளும்',
        'vis_p1' => 'கருத்துப் பெட்டியில் ஏதாவது எழுதி சம்பவத்தைச் சேமிக்கும் ஒவ்வொரு முறையும், அது சம்பவத்தின் காலவரிசையில் ஒரு பதிவாகிறது &mdash; அது யாருக்கானது என்பதை நீங்கள் தேர்வு செய்கிறீர்கள். <strong>உள்ளக குறிப்பை</strong> உங்கள் குழு மட்டுமே பார்க்கும்: சிக்கலுக்காக நீங்கள் என்ன செய்கிறீர்கள், எதை நிராகரித்தீர்கள், எந்த சப்ளையரைத் தொடர்ந்து கேட்கிறீர்கள். <strong>வெளி புதுப்பிப்பு</strong> செயலிழப்பால் பாதிக்கப்பட்டவர்களுக்காக எழுதப்படுகிறது.',
        'vis_p2' => '<strong>உள்ளகமே இயல்புநிலை, உரையாடலைத் திறக்கும் ஒவ்வொரு முறையும் அது உள்ளகத்துக்கே மீளமைக்கப்படும்.</strong> வெளியிடுவது வேண்டுமென்றே செய்யும் செயலாக இருக்க வேண்டும், தேர்வு நீங்கள் கடைசியாகத் தொட்ட சம்பவத்திலிருந்து தொடராது &mdash; இல்லையெனில் ஒரு மணி நேரத்துக்கு முன் வேறொன்றில் எடுத்த முடிவால் வெளியிட நேரிடலாம்.',
        'vis_p3' => 'காலவரிசையில் ஒவ்வொரு பதிவுக்கும் அடையாளம் இடப்படும், எனவே எதையும் திறக்காமலே எது எது என்பதை பிறகு அறியலாம்.',
        'vis_note' => 'நிர்வாகி <strong>கணினி &rarr; போர்டலில் சேவை நிலை</strong> என்பதன் கீழ் இயக்கும் வரை இறுதிப் பயனர்களுக்கு எதுவும் வெளியிடப்படாது. அதுவரை, <em>வெளி</em> என்பதைத் தேர்வுசெய்தால் புதுப்பிப்பு குறிக்கப்படும், தேர்வுக்குக் கீழுள்ள குறிப்பு உங்கள் குழுவுக்கு வெளியே இன்னும் யாரும் பார்க்க மாட்டார்கள் என்பதை வெளிப்படையாகச் சொல்லும். இந்த வசதிக்கு முன் எழுதப்பட்ட அனைத்தும் உள்ளகம், உள்ளகமாகவே இருக்கும்.',
        'corr_heading' => 'எழுத்துப்பிழையைச் சரிசெய்தல், எது புதுப்பிப்பாகக் கணக்கிடப்படும்',
        'corr_p1' => 'காலவரிசையில் ஒவ்வொரு பதிவுக்கும் ஒரு <strong>திருத்து</strong> மற்றும் ஒரு <strong>அகற்று</strong> செயல் உள்ளது. திருத்துவது ஏற்கனவே உள்ள வார்த்தைகளை மாற்றுகிறது, எனவே எழுத்துப்பிழை முதலாவதற்குச் சில நிமிடங்களுக்குப் பிறகு கிட்டத்தட்ட ஒரே மாதிரியான இரண்டாவது செய்தியாக மாறாது &mdash; வாடிக்கையாளர்கள் படிக்கும் பக்கத்தில் அது கவனக்குறைவாகத் தெரியும்.',
        'corr_p2' => 'ஒரு பதிவை <strong>யார் பார்க்கலாம்</strong> என்பதையும் பின்னர் மாற்றலாம்: வெளியிடப்பட வேண்டிய உள்ளக குறிப்பை மீண்டும் தட்டச்சு செய்யாமல் வெளியிடலாம், தவறுதலாக வெளியிடப்பட்டதை அது நடந்ததற்கான பதிவை இழக்காமல் திரும்பப் பெறலாம். பதிவு <em>நிலை</em> மற்றும் <em>சேவைப் பாதிப்புகள்</em> பற்றிச் சொல்வதை மாற்ற முடியாது &mdash; அவை அந்தக் கணத்தில் உண்மையாக இருந்தவை.',
        'corr_p3' => 'சொல்ல புதிதாக ஏதாவது இருக்கும்போது மட்டுமே சம்பவத்தைச் சேமிப்பது காலவரிசையில் சேர்க்கும்: நிலை மாறியது, வார்த்தைகள் மாறின, அல்லது பாதிக்கப்பட்ட சேவைகள் மாறின. சம்பவத்தின் பெயரை மாற்றுவது புதிய செய்தி அல்ல, சம்பவத்தைத் திறந்து சேமி அழுத்துவது எதையும் இடாது.',
        'corr_note' => 'புதிய வார்த்தைகள் இல்லாத நிலை மாற்றம் முந்தைய வாக்கியத்தை மீண்டும் சொல்லாமல் தனியாகப் பதிவு செய்யப்படும், எனவே வாசகர் &ldquo;Investigating &mdash; we are aware of delays&rdquo; என்பதைத் தொடர்ந்து &ldquo;Resolved &mdash; we are aware of delays&rdquo; என்பதைப் பார்க்க மாட்டார்.',
        'settings_heading' => 'அமைப்புகள்',
        'settings_p1' => 'அமைப்புகள் பக்கத்தில்தான் உங்கள் சேவை அட்டவணையைக் கட்டமைத்து பராமரிக்கிறீர்கள். நிலை டாஷ்போர்டில் தோன்றும் ஒவ்வொரு சேவையும் முதலில் இங்கே அமைக்கப்பட வேண்டும்.',
        'settings_step1_html' => '<strong>ஒரு சேவையைச் சேர்க்கவும்</strong> &mdash; "சேர்" என்பதைக் கிளிக் செய்து ஒரு பெயரை (எ.கா. "மின்னஞ்சல்", "VPN", "ERP அமைப்பு") மற்றும் சேவை என்ன செய்கிறது என்பதை விளக்கும் விருப்ப விளக்கத்தை வழங்கவும்.',
        'settings_step2_html' => '<strong>காட்சி வரிசையை அமைக்கவும்</strong> &mdash; வரிசை எண் டாஷ்போர்டு கட்டத்தில் சேவை எங்கே தோன்றுகிறது என்பதைக் கட்டுப்படுத்துகிறது. குறைந்த எண்கள் முதலில் தோன்றும், எனவே உங்கள் மிக முக்கியமான சேவைகளை மேலே வைக்கவும்.',
        'settings_step3_html' => '<strong>செயலில்/செயலற்ற நிலையை மாற்றவும்</strong> &mdash; ஒரு சேவையை செயலிழக்கச் செய்வது அதை நீக்காமல் டாஷ்போர்டிலிருந்து அகற்றுகிறது. செயல்நீக்கம் செய்யப்பட்ட சேவைகள் அல்லது பருவகால அமைப்புகளுக்கு இது பயனுள்ளதாக இருக்கும்.',
        'settings_step4_html' => '<strong>திருத்து அல்லது நீக்கு</strong> &mdash; சேவை விவரங்களைப் புதுப்பிக்க அல்லது ஒரு சேவையை முழுவதுமாக அகற்ற ஒவ்வொரு வரிசையிலும் உள்ள செயல் பொத்தான்களைப் பயன்படுத்தவும். வரலாற்று சம்பவ இணைப்புகள் அப்படியே இருக்க, நீக்குவதை விட திருத்துவது எப்போதும் விரும்பத்தக்கது.',
        'settings_tip' => 'உங்கள் சேவை அட்டவணையை உங்கள் நிலை பக்கத்தின் அடித்தளமாகக் கருதுங்கள். பெயர்களையும் விளக்கங்களையும் சரியாக அமைக்க நேரம் செலவிடுங்கள் &mdash; உங்கள் IT சூழலின் ஆரோக்கியத்தை உங்கள் பயனர்கள் மற்றும் பங்குதாரர்கள் சரிபார்க்கும்போது இவைதான் அவர்கள் காண்பவை.',
        'tips_heading' => 'விரைவு குறிப்புகள்',
        'tip_communicate_title' => 'விரைவில் தெரிவியுங்கள்',
        'tip_communicate_desc' => 'ஏதோ தவறு என்று தெரிந்தவுடன், எல்லா விவரங்களும் இன்னும் உங்களிடம் இல்லாவிட்டாலும், ஒரு சம்பவத்தை இடுங்கள். ஒரு சிக்கலை விரைவாக ஒப்புக்கொள்வது உங்கள் பயனர்களுடன் நம்பிக்கையை வளர்க்கிறது.',
        'tip_update_title' => 'அடிக்கடி புதுப்பிக்கவும்',
        'tip_update_desc' => 'வழக்கமான நிலை புதுப்பிப்புகள் &mdash; எதுவும் மாறவில்லை என்றாலும் &mdash; சிக்கல் தீவிரமாகச் செயல்படுத்தப்படுகிறது என்பதை பயனர்களுக்குக் காட்டுகின்றன. மௌனம் விரக்தியையும் ஆதரவு டிக்கெட்டுகளையும் உருவாக்குகிறது.',
        'tip_review_title' => 'வடிவங்களை மதிப்பாய்வு செய்யுங்கள்',
        'tip_review_desc' => 'உங்கள் சம்பவ வரலாற்றை தவறாமல் சரிபார்க்கவும். அதே சேவை மீண்டும் மீண்டும் தோன்றினால், அது முன்கூட்டியே கவனிக்கத்தக்க ஆழமான உள்கட்டமைப்பு சிக்கலைச் சுட்டிக்காட்டலாம்.',
        'planned_heading' => 'திட்டமிட்ட பராமரிப்பு',
        'planned_p1' => 'வேலை நடப்பதற்கு முன் மக்களுக்குத் தெரிவிக்க திட்டமிட்ட பராமரிப்பின் கீழ் திட்டமிடு அழுத்துங்கள்: தலைப்பு, அது எப்போது தொடங்கும் மற்றும் (விருப்பமாக) முடியும், மக்கள் அறிய வேண்டியவை, மற்றும் அது பாதிக்கும் சேவைகள் ஒரு பாதிப்புடன் - நீங்கள் வேறு தேர்ந்தெடுக்காவிட்டால் Maintenance. அது உடனே வரவிருப்பதாகக் காட்டப்படும், இங்கும், சம்பவங்கள் காட்டப்பட்டால் போர்டலிலும், சேவைகளில் எதையும் மாற்றாது.',
        'planned_p2' => 'தொடக்கத்தில் அது அந்தச் சேவைகளில் சாதாரண சம்பவமாக மாறும், திட்டமிட்ட தொடக்க நேரத்தில் தேதியிடப்பட்டு, உங்கள் வார்த்தைகள் அதன் முதல் வெளி புதுப்பிப்பாக இருக்கும் - எனவே அதன் பணிப்பாய்வுகள் இயங்கும், அதன் வரலாறு அப்போது நீங்களே உருவாக்கியது போலப் படிக்கும். முடிவில் அது தீர்க்கப்படும், திட்டமிட்ட முடிவு நேரத்தில் தேதியிடப்படும். கைமுறையாகத் தீர்க்க முடிவை காலியாக விடுங்கள். நீங்களே முன்கூட்டியே தீர்ப்பது சரிதான்; உங்கள் நேரம் நிலைக்கும்.',
        'planned_p3' => 'தொடங்கும் வரை திருத்து மூலம் அதை மாற்றலாம் அல்லது திரும்பப்பெறலாம். தொடங்கியதும் அது ஒரு சம்பவம்: திற மூலம் அங்கே மாற்றுங்கள்.',
        'planned_note' => 'தொடக்கங்களும் முடிவுகளும் யாராவது இந்தப் பக்கம், போர்டல் அல்லது Watchtower-ஐத் திறக்கும்போதும், திட்டமிடப்பட்ட பணிப்பாய்வு வேலையால் (cron/workflow_scheduled.php) கவனிக்கப்படுகின்றன - எனவே யாரும் பார்க்காதபோதும் தொடக்கம் சரியான நேரத்தில் நடக்க வேண்டுமெனில் அந்த வேலையை அட்டவணையிடுங்கள். Maintenance நிலை அப்டைமுக்கு எதிராகக் கணக்கிடப்படாது. ஒரு திட்டப்பணி அதன் Connections தாவலிலிருந்து திட்டமிட்ட பராமரிப்பை அறிவிக்கலாம்.',
        'tip_maintenance_title' => 'பராமரிப்பைத் திட்டமிடுங்கள்',
        'tip_maintenance_desc' => 'முன்கூட்டியே தெரிந்த வேலைக்கு திட்டமிட்ட பராமரிப்பைப் பயன்படுத்துங்கள். அது உடனே அறிவிக்கப்படும், வேலை தொடங்கும்போது மட்டுமே - அப்டைமுக்கு எதிராகக் கணக்கிடப்படாத Maintenance நிலையில் - சம்பவமாக மாறும்.',
    ],
];
